using System; using System.Collections.Generic; using System.IO; using UnityEngine;
namespace NWD.Save {
 [Serializable] public sealed class SaveGameData { public int version=1; public string manifestHash; public string nodeId; public int canonicalIndex; public string checkpoint; public string protagonist; public string difficulty; public List<string> activeSquad=new(), deadCharacters=new(), rescuedCharacters=new(), infectedCharacters=new(), irreversibleEvents=new(), viewedCinematics=new(), inventory=new(), weapons=new(), persistentObjectives=new(); public int ammunition; public float health; public bool IsComplete()=>version>0&&!string.IsNullOrWhiteSpace(manifestHash)&&!string.IsNullOrWhiteSpace(nodeId)&&canonicalIndex>=0; }
 public interface ISaveService { SaveGameData Load(); void Save(SaveGameData data); }
 public sealed class JsonSaveService:ISaveService { readonly string path; public JsonSaveService(string path){this.path=path;} public SaveGameData Load()=>File.Exists(path)?JsonUtility.FromJson<SaveGameData>(File.ReadAllText(path)):null; public void Save(SaveGameData d){if(d==null||!d.IsComplete())throw new InvalidDataException("Refusing incomplete save"); var json=JsonUtility.ToJson(d,true); if(!JsonUtility.FromJson<SaveGameData>(json).IsComplete())throw new InvalidDataException("Save validation failed"); Directory.CreateDirectory(Path.GetDirectoryName(path)); var tmp=path+".tmp"; File.WriteAllText(tmp,json); if(File.Exists(path))File.Replace(tmp,path,path+".bak"); else File.Move(tmp,path); } }
}
